{
  "table": {
    "name": "Votes",
    "purpose": "One row per vote cast on a post of a Stack Exchange-style Q&A site (the sibling tables posts, users, comments, badges, tags, postHistory, postLinks are exactly the Stack Exchange data-dump schema). \"Vote\" is used broadly: upvotes, downvotes, answer acceptance, favorites, bounties and moderation/spam/close events, distinguished by VoteTypeId. The data covers the site's first ~9 months (2010-07-19 to 2011-05-01), with the busiest days falling in the launch week of July 2010."
  },
  "columns": {
    "BountyAmount": {
      "role": "boolean",
      "name": "Bounty amount",
      "description": "Reputation points pledged or awarded as a bounty on the post. Populated on only ~0.3% of rows (117 of 38,930) - i.e. exclusively on the bounty-related votes (Stack Exchange VoteTypeId 8 = bounty start, 9 = bounty close); null for every ordinary vote. Observed values 0, 25, 50, 100, 150, 200 (median 50, max 200), the typical Stack Exchange bounty sizes; the 25 and 0 values plausibly reflect half-auto-awarded and unawarded bounties.",
      "status": "resolved"
    },
    "CreationDate": {
      "role": "date",
      "name": "Vote date",
      "description": "Date the vote was cast, stored as a YYYY-MM-DD string (declared VARCHAR; no time component - all values are midnight). Range 2010-07-19 to 2011-05-01; the highest-volume days (2010-07-19/20/21/27, 300-464 votes) are the site's launch week.",
      "status": "resolved"
    },
    "Id": {
      "role": "foreign_key",
      "name": "Vote ID",
      "description": "Surrogate primary key of the vote row: unique across all 38,930 rows, values 1-43,538. The max exceeding the row count implies some vote rows were deleted or excluded from the dump.",
      "status": "resolved"
    },
    "PostId": {
      "role": "foreign_key",
      "name": "Post ID",
      "description": "Foreign key to posts.Id - the question or answer that received the vote (many-to-one: 8,584 distinct posts are voted on, up to 81 votes on a single post).",
      "status": "resolved"
    },
    "UserId": {
      "role": "foreign_key",
      "name": "Voter user ID",
      "description": "Foreign key to users.Id - the user who cast the vote. Null on 91.2% of rows because ordinary votes (up/down/accept) are anonymized in this dump; the ~3,426 non-null rows correspond to the vote types whose voter is public: the 3,365 favorites (VoteTypeId 5) plus roughly 60 bounty votes. The most frequent values (user 253 with 319 votes, user 3911 with 313) are users who favorited/bountied many posts.",
      "status": "resolved"
    },
    "VoteTypeId": {
      "role": "category",
      "name": "Vote type code",
      "description": "Categorical code for the kind of vote, following the standard Stack Exchange vote-type encoding; it is an enum, not a foreign key (the accepted joins to posts.Id / postHistory.Id are spurious small-integer matches). The distribution pins the main codes: 2 = upvote (33,323 rows, 85.6%), 5 = favorite (3,365 - matching the non-null UserId count), 1 = accepted answer (1,451), 3 = downvote (444), 16 = post moderated (111). Sample values add 8, 9 and 10: 8 = bounty start and 9 = bounty close/award (the rows that carry BountyAmount), 10 = deletion. Two further distinct codes (10 distinct in total) cannot be identified from this profile alone; per the same encoding the remaining candidates are 4 offensive, 6 close, 7 reopen, 11 undeletion, 12 spam, 13 moderator review.",
      "status": "resolved"
    }
  }
}
